from pathlib import Path
import json
P=Path(__file__).resolve().parent
data={g:json.loads((P/f'{g}-manifest.json').read_text())['states'][0] for g in ['bare','helmet']}
for gear,state in data.items():state['frameFiles']=[p.split('/veld-sofa-fall-south-v1/')[1] for p in state['frameFiles']]
markup='''<p>Finite source preview at one-third speed. This common source entrance is the held tablet pose; the native boards below show the exact six different incoming reading poses. Source playback does not reproduce the sofa world offset.</p><select id="gear"><option value="bare">Bare</option><option value="helmet">Helmet</option></select> <button id="play">Replay</button><p id="status"></p><canvas width="256" height="272" id="pose" style="background:#26353d"></canvas><script>const data=DATA;let images={},start=performance.now();function reset(){start=performance.now()}const gear=document.querySelector('#gear');gear.onchange=reset;document.querySelector('#play').onclick=reset;Promise.all(Object.values(data).flatMap(s=>s.frameFiles).map(p=>new Promise((yes,no)=>{let im=new Image();im.onload=()=>{images[p]=im;yes()};im.onerror=no;im.src=p}))).then(()=>{function draw(now){const s=data[gear.value];let t=Math.min(1520,(now-start)/3),slot=0;while(slot<5&&t>=s.frameDurationsMs[slot])t-=s.frameDurationsMs[slot++];let c=document.querySelector('#pose').getContext('2d');c.clearRect(0,0,256,272);c.drawImage(images[s.frameFiles[slot]],0,0);document.querySelector('#status').textContent=gear.value+' / pose '+slot+' of 5';requestAnimationFrame(draw)}requestAnimationFrame(draw)})</script>'''.replace('DATA',json.dumps(data))
p=P/'review.html';page=p.read_text(encoding='utf-8');page=page.replace('<img src="paired-source-review.png">',markup+'<p><img src="paired-source-review.png"></p>');p.write_text(page,encoding='utf-8')
print('Finite paired source playback added; native boards retained')
